function bindProduct(id){$$('[data-off]').forEach(b=>b.onclick=()=>{OFF=+b.dataset.off;G=0;rerender(true)});$$('[data-g]').forEach(b=>b.onclick=()=>{G=+b.dataset.g;rerender(true)});$$('[data-q]').forEach(b=>b.onclick=()=>{QTY=Math.max(1,QTY+ +b.dataset.q);rerender(true)});const a=$('[data-addp]');if(a)a.onclick=()=>{const p=PROD[id];addCart(id,QTY,p.offers&&p.offers[OFF]?p.offers[OFF].id:'')}}
