let stageTab=0,stageOk=false;
function renderStage(){const el=$('#rStage');if(!el)return;const tabs=['Фотофиксация','Документы','График'];
el.innerHTML=`<div style="display:flex;justify-content:space-between;gap:10px;align-items:flex-start"><div><div class="small" style="font-size:11px;text-transform:uppercase;letter-spacing:.12em;font-weight:600">Пример личного кабинета</div><div class="serif" style="font-size:28px;line-height:1.1;margin-top:6px">Подготовка стен</div><div class="small" style="font-size:12px">Этап 03 · перед финишной отделкой</div></div><span class="tag" style="border-color:${stageOk?'var(--ink)':'var(--red)'};color:${stageOk?'var(--ink)':'var(--red)'}">${stageOk?'Принят ✓':'Готов к проверке'}</span></div>
<div class="lk-tabs">${tabs.map((t,i)=>`<button class="${i===stageTab?'on':''}" data-st="${i}">${t}</button>`).join('')}</div>
<div class="fade">${stageTab===0?`<div style="aspect-ratio:4/3;overflow:hidden;cursor:zoom-in" data-zoomk="repair">${im('repair','Фотофиксация этапа')}</div><p class="small" style="font-size:12px;margin:8px 0 0">Место для фотофиксации исполнителя по завершении этапа</p>`:stageTab===1?['Акт скрытых работ','Акт приёмки этапа 03','Фото до/после'].map(d=>`<div style="display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line);font-size:14px"><span>${d}</span><span class="small">PDF</span></div>`).join(''):[['Подготовка','✓ принят'],['Электрика','✓ принят'],['Подготовка стен','проверка'],['Финишная отделка','далее']].map(d=>`<div style="display:flex;justify-content:space-between;padding:12px 0;border-bottom:1px solid var(--line);font-size:14px"><span>${d[0]}</span><span class="small">${d[1]}</span></div>`).join('')}</div>
<div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn sm" data-stok ${stageOk?'disabled style="opacity:.5"':''}>${stageOk?'Этап принят ✓':'Принять этап'}</button><button class="btn ghost sm" data-stnote>Есть замечания</button></div>
<p class="small" style="font-size:11px;margin:0">Демонстрация: действия в прототипе не принимают реальные работы.</p>`;hydrate(el);
$$('[data-st]',el).forEach(b=>b.onclick=()=>{stageTab=+b.dataset.st;renderStage()});const ok=$('[data-stok]',el);if(ok)ok.onclick=()=>{stageOk=true;renderStage();toast('Этап «Подготовка стен» принят — теперь можно оплатить')};$('[data-stnote]',el).onclick=()=>toast('Замечание зафиксировано — исполнитель получит уведомление')}
let subObs;
function bindRepair(){renderStage();$$('[data-cmp]').forEach(b=>b.onclick=()=>{const i=+b.dataset.cmp;cmpSel.has(i)?cmpSel.delete(i):cmpSel.add(i);const art=b.closest('.co');art.classList.toggle('on',cmpSel.has(i));b.classList.toggle('ghost',!cmpSel.has(i));b.textContent=cmpSel.has(i)?'✓ Выделено':'Выделить для сравнения'});bindForms($('#app'));
const links=$$('[data-sub]');subObs=new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting)links.forEach(l=>l.classList.toggle('on',l.dataset.sub===en.target.id))}),{rootMargin:'-40% 0px -55% 0px'});links.forEach(l=>{const s=document.getElementById(l.dataset.sub);s&&subObs.observe(s)})}

